import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { AccountEnvironmentService } from 'app/core/account/account-environment.service';
import { AuthService } from 'app/core/auth/auth.service';
import { AuthUtils } from 'app/core/auth/auth.utils';
import { SessionService } from 'app/core/services/session.service';
import { UserService } from 'app/core/user/user.service';
import { AgentWalletService } from 'app/modules/chat/services/agent-wallet.service';
import {
    defaultValueForDependency,
    paramValueForDependency,
    resolveHumanAuthnDependencies,
    shouldListHumanAuthnParams,
} from './human-authn-postman.catalog';
import { attachColombiaCedulaPremiumPricing } from './postman-billing.util';
import {
    CatalogCountryRow,
    DEFAULT_POSTMAN_COUNTRY,
    catalogCountryScope,
    catalogNeedsDetailHydration,
    countryCacheKey,
    endpointMatchesCountryFilter,
    extractCountryRows,
    extractFeatureRows,
    isCatalogTransportFailure,
} from './postman-catalog.util';
import {
    POSTMAN_INCLUDE_COST_KEY,
    ensurePostmanIncludeCostParam,
    removePostmanIncludeCostParam,
    resolvePostmanIncludeCostForSend,
} from './postman-include-cost.util';
import {
    getPostmanRequestValidationIssues,
    getPostmanXorGroupMetadata,
} from './postman-request-validation';
import { normalizePostmanSexoValue } from './postman-sexo.util';
import { buildPostmanEffectiveUrl, getPostmanPathParamKeysForEndpoint } from './postman-url.util';
import {
    API_ENDPOINTS,
    ApiEndpoint,
    PostmanDependencyMeta,
    PostmanEndpointRowDto,
    PostmanFolderDto,
    PostmanLayoutData,
    PostmanLayoutResponse,
} from './postman.types';
import { applyPostmanSandboxParamDefaults } from './sandbox';

import { TranslocoService } from '@jsverse/transloco';
import { isBiometricsEndpoint } from 'app/modules/smart-enroll/biometrics/biometrics.constants';
import { environment } from 'environments/environment';
import {
    Observable,
    catchError,
    distinctUntilChanged,
    finalize,
    forkJoin,
    map,
    of,
    skip,
    tap,
    throwError,
} from 'rxjs';
import { mergeParamsFromDocs } from './postman-docs-params.util';
import { postmanEndpointDetailCache } from './postman-endpoint-detail.cache';
import { isClientVisibleBatchDependencyField } from '../smart-batch/smart-batch-dependency.constants';

@Injectable({
    providedIn: 'root',
})
export class PostmanService {
    private _sessionService = inject(SessionService);
    private _userService = inject(UserService);
    private _authService = inject(AuthService);
    private _agentWalletService = inject(AgentWalletService);
    private _accountEnv = inject(AccountEnvironmentService);
    private _transloco = inject(TranslocoService);

    endpoints = signal<ApiEndpoint[]>(API_ENDPOINTS);

    /** When set, sidebar and explorer only show endpoints in these categories (or face_recognition codes). */
    categoryFilter = signal<string[] | null>(null);

    visibleEndpoints = computed(() => {
        const all = this.endpoints();
        const categories = this.categoryFilter();
        if (!categories?.length) return all;
        return all.filter((ep) => isBiometricsEndpoint(ep.category, ep.code));
    });

    setCategoryFilter(categories: readonly string[] | null): void {
        this.categoryFilter.set(categories?.length ? [...categories] : null);
    }

    clearCategoryFilter(): void {
        this.categoryFilter.set(null);
    }

    layoutFolders = signal<PostmanFolderDto[]>([]);
    layoutEndpointsRaw = signal<PostmanEndpointRowDto[]>([]);
    layoutLoaded = signal(false);
    layoutLoading = signal(false);
    /** Transloco key for layout GET failure (optional toast copy) */
    layoutError = signal<string | null>(null);

    /** When true, sidebar uses folder tree + Library; catalog-only grouping for guests. */
    useLayoutSidebar = computed(() => {
        if (!this.layoutLoaded()) {
            return false;
        }
        return this._canUseWorkspacePostmanApis();
    });

    selectedEndpoint = signal<ApiEndpoint | null>(null);
    selectedCountry = signal<string | null>(DEFAULT_POSTMAN_COUNTRY);
    catalogCountries = signal<CatalogCountryRow[]>([]);
    detailLoading = signal(false);
    response = signal<any>(null);
    responseTime = signal<number | null>(null);
    isLoading = signal<boolean>(false);
    error = signal<any>(null);
    paymentMethod = signal<'credits' | 'x402'>('credits');
    private _featureCache = new Map<string, ApiEndpoint[]>();
    private _loadedScopeKey = '';
    private _requestedScopeKey = '';

    constructor(private _httpClient: HttpClient) {
        this.loadExplorerData();
        // Only reload when identity or JWT workspace claims change (login, logout,
        // linking a Verifik client). Credit-only tweaks keep the same keys → no reload.
        this._userService.user$
            .pipe(
                skip(1),
                map((user) => ({
                    identityKey: (user as any)?._id || (user as any)?.id || null,
                    workspacePostman: this._canUseWorkspacePostmanApis(),
                })),
                distinctUntilChanged(
                    (a, b) =>
                        a.identityKey === b.identityKey && a.workspacePostman === b.workspacePostman
                )
            )
            .subscribe(() => {
                this.loadExplorerData();
            });
    }

    private _authHeaders(): Record<string, string> {
        const token = localStorage.getItem('accessToken');
        return token ? { Authorization: `Bearer ${token}` } : {};
    }

    private _apiUrl(): string {
        return environment.apiUrl;
    }

    /**
     * Workspace-only Postman APIs (`/v2/app-features/my-list`, `/v2/postman/layout`, folder CRUD)
     * require JWT claims `clientId`, `staffId`, or `superAdminId`. Smart Agent tokens that are only
     * “logged in” to a project often omit those claims; catalog + explorer must use `/v2/public/app-features`.
     */
    private _canUseWorkspacePostmanApis(): boolean {
        if (!this._sessionService.isTokenValid()) {
            return false;
        }
        const token = localStorage.getItem('accessToken');
        if (!token?.trim()) {
            return false;
        }
        const payload = AuthUtils.getJwtPayload(token);
        if (!payload) {
            return false;
        }
        const clientId = payload['clientId'];
        const staffId = payload['staffId'];
        const superAdminId = payload['superAdminId'];
        return Boolean(clientId ?? staffId ?? superAdminId);
    }

    /** Same as `_canUseWorkspacePostmanApis` — exposed for UI (e.g. request editor) that must not call workspace-only APIs as guests. */
    canUseWorkspacePostmanApis(): boolean {
        return this._canUseWorkspacePostmanApis();
    }

    /**
     * Loads the country index, a slim country-scoped catalog, and Postman layout.
     */
    loadExplorerData(countries?: string[]): void {
        this.layoutLoading.set(true);
        this.layoutError.set(null);
        this._featureCache.clear();
        const scope = countries?.length ? countries : catalogCountryScope(this.selectedCountry());
        this._requestedScopeKey = countryCacheKey(scope);

        forkJoin({
            countries: this._fetchCatalogCountries(),
            features: this._fetchSlimFeatures(scope),
            layout: this._fetchLayout(),
        })
            .pipe(
                tap(({ countries: countryRows, features, layout }) => {
                    this.catalogCountries.set(countryRows);
                    this._applyLayoutPayload(layout);
                    this._commitFeaturePayload(scope, features);
                }),
                finalize(() => {
                    this.layoutLoading.set(false);
                    this.layoutLoaded.set(true);
                })
            )
            .subscribe();
    }

    /**
     * Fetches slim features for the given countries (plus cache). Used when switching pills.
     */
    loadFeaturesForCountries(countries: string[]): void {
        const scope = countries.length ? countries : catalogCountryScope(this.selectedCountry());
        const cacheKey = countryCacheKey(scope);
        this._requestedScopeKey = cacheKey;
        const cached = this._featureCache.get(cacheKey);
        if (cached && cacheKey === this._loadedScopeKey) {
            return;
        }
        if (cached) {
            this._loadedScopeKey = cacheKey;
            this._setEndpointsFromCatalog(cached);
            return;
        }

        this.layoutLoading.set(true);
        this._fetchSlimFeatures(scope)
            .pipe(
                tap((features) => this._commitFeaturePayload(scope, features)),
                finalize(() => this.layoutLoading.set(false))
            )
            .subscribe();
    }

    /**
     * Opens an endpoint by feature code, loading its country scope when needed.
     */
    openEndpointByCode(code: string): void {
        const existing = this.endpoints().find((endpoint) => endpoint.code === code);
        if (existing) {
            this.selectEndpoint(existing);
            return;
        }

        this._fetchFeatureDetail(code).subscribe((feature) => {
            if (!feature) return;
            const country = feature.country || null;
            if (country && this.selectedCountry() !== country) {
                this.selectedCountry.set(country);
            }
            this.loadFeaturesForCountries(catalogCountryScope(country));
            this.selectEndpoint(this._createEndpointFromFeature(feature, this._apiUrl()));
        });
    }

    private _fetchCatalogCountries() {
        const apiUrl = this._apiUrl();
        const workspaceUrl = `${apiUrl}/v2/app-features/countries`;
        const publicUrl = `${apiUrl}/v2/public/app-features/countries`;
        const source$ = this._canUseWorkspacePostmanApis()
            ? this._httpClient.get<any>(workspaceUrl).pipe(
                  catchError((err) => {
                      console.error('Failed to fetch catalog countries', err);
                      return this._httpClient.get<any>(publicUrl);
                  })
              )
            : this._httpClient.get<any>(publicUrl);

        return source$.pipe(
            map((payload) => extractCountryRows(payload)),
            catchError((err) => {
                console.error('Failed to fetch catalog countries', err);
                return of([] as CatalogCountryRow[]);
            })
        );
    }

    private _catalogListParams(countries: string[]): HttpParams {
        return countries
            .filter(Boolean)
            .reduce((params, country) => params.append('in_country', country), new HttpParams());
    }

    private _fetchSlimFeatures(countries: string[]) {
        const apiUrl = this._apiUrl();
        const params = this._catalogListParams(countries);
        const workspaceUrl = `${apiUrl}/v2/app-features/my-list`;
        const publicUrl = `${apiUrl}/v2/public/app-features`;
        const public$ = this._httpClient.get<any>(publicUrl, { params });
        const source$ = this._canUseWorkspacePostmanApis()
            ? this._httpClient.get<any>(workspaceUrl, { params }).pipe(
                  catchError((err) => {
                      if (isCatalogTransportFailure(err)) {
                          console.error(
                              'Catalog list transport failed; retrying public slim list',
                              err
                          );
                      } else {
                          console.error('Failed to fetch features', err);
                      }
                      return public$;
                  })
              )
            : public$;

        return source$.pipe(
            catchError((err) => {
                console.error('Failed to fetch features', err);
                return of({ data: [] });
            })
        );
    }

    private _fetchLayout() {
        if (!this._canUseWorkspacePostmanApis()) {
            return of(null);
        }
        return this._httpClient
            .get<PostmanLayoutResponse>(`${this._apiUrl()}/v2/postman/layout`, {
                headers: this._authHeaders(),
            })
            .pipe(
                catchError((err) => {
                    console.error('Failed to fetch postman layout', err);
                    this.layoutError.set('postman.sidebar.layoutLoadError');
                    return of(null);
                })
            );
    }

    private _applyLayoutPayload(layout: PostmanLayoutResponse | null): void {
        const layoutData = layout?.data ?? null;
        this.layoutFolders.set((layoutData?.folders ?? []).map((f) => this._normalizeFolderDto(f)));
        this.layoutEndpointsRaw.set(
            (layoutData?.endpoints ?? []).map((e) => this._normalizeEndpointDto(e))
        );
    }

    private _commitFeaturePayload(countries: string[], features: unknown): void {
        const apiUrl = this._apiUrl();
        const allFeatures = extractFeatureRows(features).filter(
            (feature: { isAvailable?: boolean; deleted?: boolean }) =>
                feature?.isAvailable !== false && feature?.deleted !== true
        );
        const catalogFeatures = allFeatures.filter(
            (feature: { catalogHidden?: boolean }) => feature?.catalogHidden !== true
        );
        const dynamicEndpoints = catalogFeatures.map((feature: any) =>
            this._createEndpointFromFeature(feature, apiUrl)
        );
        const mergedCatalog = attachColombiaCedulaPremiumPricing(
            this._mergeEndpoints(API_ENDPOINTS, dynamicEndpoints),
            allFeatures
        );
        const withLayout = this._applyPostmanLayout(mergedCatalog, {
            folders: this.layoutFolders(),
            endpoints: this.layoutEndpointsRaw(),
        });
        const scoped = withLayout.filter((endpoint) =>
            countries.some((country) => endpointMatchesCountryFilter(endpoint.country, country))
        );
        const cacheKey = countryCacheKey(countries);
        this._featureCache.set(cacheKey, scoped);
        if (cacheKey !== this._requestedScopeKey) {
            return;
        }
        this._loadedScopeKey = cacheKey;
        this._setEndpointsFromCatalog(scoped);
    }

    private _setEndpointsFromCatalog(withLayout: ApiEndpoint[]): void {
        this.endpoints.set(withLayout);
        this.selectedEndpoint.update((current) => {
            if (!current) return current;
            const match = withLayout.find((endpoint) => this._isSameEndpoint(endpoint, current));
            if (!match) return current;
            return {
                ...match,
                headers: current.headers?.length ? current.headers : match.headers,
                params: this._mergeEndpointParams(current.params, match.params),
                body: current.body ?? match.body,
                docs: current.docs ?? match.docs,
                dependencies: current.dependencies?.length
                    ? current.dependencies
                    : match.dependencies,
            };
        });
    }

    private _rememberFeatureDetail(feature: unknown): void {
        const row =
            feature && typeof feature === 'object'
                ? (feature as { code?: string; _id?: string })
                : null;
        const key = row?.code || row?._id;

        if (!key) return;

        postmanEndpointDetailCache.set(String(key), feature);
    }

    private _fetchFeatureDetail(codeOrId: string) {
        const cached = postmanEndpointDetailCache.get(codeOrId);

        if (cached) return of(cached);

        const apiUrl = this._apiUrl();
        const public$ = this._httpClient.get<any>(
            `${apiUrl}/v2/public/app-features/${encodeURIComponent(codeOrId)}`
        );
        const workspace$ =
            this._canUseWorkspacePostmanApis() && /^[a-fA-F0-9]{24}$/.test(codeOrId)
                ? this._httpClient
                      .get<any>(`${apiUrl}/v2/app-features/${codeOrId}`)
                      .pipe(catchError(() => public$))
                : public$;

        return workspace$.pipe(
            map((payload) => payload?.data ?? null),
            tap((feature) => this._rememberFeatureDetail(feature)),
            catchError((err) => {
                console.error('Failed to fetch feature detail', err);
                return of(null);
            })
        );
    }

    /**
     * Loads docs and extra params for one slim catalog row.
     */
    hydrateEndpointDetails(endpoint: ApiEndpoint): Observable<ApiEndpoint> {
        if (!catalogNeedsDetailHydration(endpoint)) {
            return of(endpoint);
        }
        const codeOrId = endpoint.code || endpoint.id;
        if (!codeOrId) {
            return of(endpoint);
        }

        const cached = postmanEndpointDetailCache.get(codeOrId);
        if (cached) {
            return of(this._mergeHydratedFeature(endpoint, cached));
        }

        this.detailLoading.set(true);
        return this._fetchFeatureDetail(codeOrId).pipe(
            map((feature) => (feature ? this._mergeHydratedFeature(endpoint, feature) : endpoint)),
            finalize(() => this.detailLoading.set(false))
        );
    }

    private _mergeHydratedFeature(endpoint: ApiEndpoint, feature: unknown): ApiEndpoint {
        const hydrated = this._createEndpointFromFeature(feature, this._apiUrl());
        return {
            ...endpoint,
            ...hydrated,
            headers: endpoint.headers?.length ? endpoint.headers : hydrated.headers,
            params: this._mergeEndpointParams(endpoint.params, hydrated.params),
            body: endpoint.body ?? hydrated.body,
            docs: hydrated.docs ?? endpoint.docs,
            dependencies: hydrated.dependencies?.length
                ? hydrated.dependencies
                : endpoint.dependencies,
        };
    }

    private _normalizeFolderDto(f: PostmanFolderDto): PostmanFolderDto {
        return {
            ...f,
            _id: String(f._id),
            parentFolder: f.parentFolder != null ? String(f.parentFolder) : null,
        };
    }

    private _normalizeEndpointDto(e: PostmanEndpointRowDto): PostmanEndpointRowDto {
        return {
            ...e,
            _id: String(e._id),
            folder: e.folder != null ? String(e.folder) : null,
        };
    }

    private _applyPostmanLayout(
        catalog: ApiEndpoint[],
        layoutData: Pick<PostmanLayoutData, 'folders' | 'endpoints'> | null | undefined
    ): ApiEndpoint[] {
        if (!layoutData || (!layoutData.endpoints?.length && !layoutData.folders?.length)) {
            return catalog.map((ep) => ({ ...ep }));
        }

        const folderIds = new Set(
            (layoutData.folders || []).map((f) => String((f as PostmanFolderDto)._id))
        );
        const byCode = new Map<string, PostmanEndpointRowDto>();
        for (const row of layoutData.endpoints || []) {
            if (row.appFeatureCode) {
                byCode.set(
                    row.appFeatureCode,
                    this._normalizeEndpointDto(row as PostmanEndpointRowDto)
                );
            }
        }

        return catalog.map((ep) => {
            if (!ep.code) {
                return { ...ep };
            }
            const row = byCode.get(ep.code);
            if (!row) {
                return { ...ep };
            }
            let folderId: string | null = null;
            if (row.folder) {
                const fid = String(row.folder);
                folderId = folderIds.has(fid) ? fid : null;
            }
            return {
                ...ep,
                postmanEndpointId: row._id,
                postmanFolderId: folderId,
                layoutSortOrder: typeof row.sortOrder === 'number' ? row.sortOrder : 0,
                layoutDisplayName: row.displayName?.trim() ? row.displayName : undefined,
                isFavorite: !!row.isFavorite,
            };
        });
    }

    /**
     * Normalizes API `baseCategory` / `group` to a stable UPPER_SNAKE string for
     * grouping and `categories.*` i18n keys (avoids keys with spaces or apostrophes).
     */
    private _mapCategory(category: string): string {
        if (!category) {
            return 'OTHER';
        }
        return category
            .trim()
            .toUpperCase()
            .replace(/'/g, '')
            .replace(/[\s-]+/g, '_')
            .replace(/_+/g, '_');
    }

    private _createEndpointFromFeature(feature: any, apiUrl: string): ApiEndpoint {
        const method = feature.group === 'apiRequest' ? 'GET' : feature.method || 'POST';
        const rawDeps = resolveHumanAuthnDependencies(feature.code, feature.dependencies);
        const dependencies = this._toPostmanDependencyMeta(rawDeps);
        const xorMeta = dependencies.length ? getPostmanXorGroupMetadata(dependencies) : null;
        const listParams = method === 'GET' || shouldListHumanAuthnParams(feature.code);

        const created: ApiEndpoint = {
            id: feature._id || feature.code,
            label: feature.name,
            ...(typeof feature.nameES === 'string' && feature.nameES.trim()
                ? { nameES: feature.nameES.trim() }
                : {}),
            code: feature.code,
            category: this._mapCategory(feature.baseCategory || feature.group),
            country: feature.country,
            ...(Array.isArray(feature.checkListDomains) && feature.checkListDomains.length
                ? { checkListDomains: feature.checkListDomains }
                : {}),
            method,
            url: feature.url
                ? feature.url.startsWith('http')
                    ? feature.url
                    : `${apiUrl}/${feature.url}`
                : '',
            description: feature.description,
            estimatedCost: feature.price ?? 0,
            headers: [
                { key: 'Content-Type', value: 'application/json' },
                {
                    key: 'Authorization',
                    value: 'Bearer <token>',
                },
            ],
            ...(dependencies.length ? { dependencies } : {}),
            params: listParams ? this._paramsFromDependencies(rawDeps, xorMeta) : [],
            body: method !== 'GET' && rawDeps.length ? this._bodyFromDependencies(rawDeps) : null,
            ...(feature.docs && typeof feature.docs === 'object' ? { docs: feature.docs } : {}),
        };
        if (!created.docs && created.code) {
            const cached = postmanEndpointDetailCache.get(created.code);
            const cachedDocs =
                cached && typeof cached === 'object'
                    ? (cached as { docs?: ApiEndpoint['docs'] }).docs
                    : undefined;
            if (cachedDocs && typeof cachedDocs === 'object') {
                created.docs = cachedDocs;
            }
        }
        return mergeParamsFromDocs(created);
    }

    private _toPostmanDependencyMeta(rawDeps: any[]): PostmanDependencyMeta[] {
        return rawDeps.map((dependency) => ({
            field: dependency.field,
            type: dependency.type,
            required: dependency.required,
            enum: dependency.enum ?? undefined,
            description: dependency.description,
            dependencyGroup: dependency.dependencyGroup,
            requiredWhen: dependency.requiredWhen,
            dateFormat: dependency.dateFormat,
        }));
    }

    private _paramsFromDependencies(
        rawDeps: any[],
        xorMeta: ReturnType<typeof getPostmanXorGroupMetadata>
    ) {
        return rawDeps
            .filter((dependency) => isClientVisibleBatchDependencyField(dependency.field))
            .map((dependency) => {
            const groupId =
                dependency.dependencyGroup != null ? String(dependency.dependencyGroup).trim() : '';
            const isXorDocumentType =
                dependency.field === 'documentType' &&
                xorMeta &&
                groupId.length > 0 &&
                xorMeta.docGroupIds.has(groupId);
            const defaultVal = isXorDocumentType
                ? (dependency.default ?? '')
                : paramValueForDependency(dependency);
            let desc = dependency.description;
            if (!desc && dependency.enum && dependency.enum.length) {
                desc = this._transloco.translate('postman.requestEditor.params.pickValue', {
                    values: dependency.enum.join(', '),
                });
            }
            const enumList =
                Array.isArray(dependency.enum) && dependency.enum.length
                    ? [...dependency.enum]
                    : undefined;

            return {
                key: dependency.field,
                value: typeof defaultVal === 'string' ? defaultVal : String(defaultVal ?? ''),
                type: dependency.type,
                required: dependency.required,
                description: desc,
                ...(enumList ? { enum: enumList } : {}),
                ...(groupId ? { dependencyGroup: groupId } : {}),
                ...(dependency.requiredWhen ? { requiredWhen: dependency.requiredWhen } : {}),
                ...(dependency.dateFormat ? { dateFormat: dependency.dateFormat } : {}),
            };
        });
    }

    private _bodyFromDependencies(rawDeps: any[]): Record<string, unknown> {
        return rawDeps.reduce((acc: Record<string, unknown>, dep) => {
            acc[dep.field] = defaultValueForDependency(dep);
            return acc;
        }, {});
    }

    /**
     * Merges static catalog params with API-derived params by `key` so metadata such as `enum`
     * from the feature list is preserved while keeping user-facing `value` from the catalog.
     */
    private _mergeEndpointParams(
        existing: ApiEndpoint['params'],
        match: ApiEndpoint['params']
    ): ApiEndpoint['params'] {
        if (!match?.length) {
            return existing?.length ? existing : match;
        }
        if (!existing?.length) {
            return match;
        }

        type ParamRow = NonNullable<ApiEndpoint['params']>[number];
        const matchByKey = new Map<string, ParamRow>(match.map((p) => [p.key, p]));
        const merged: ParamRow[] = [];
        const consumedKeys = new Set<string>();

        for (const ex of existing) {
            const m = matchByKey.get(ex.key);
            if (m) {
                consumedKeys.add(ex.key);
                merged.push(this._mergeParamRow(ex, m));
            } else {
                merged.push({ ...ex });
            }
        }

        for (const m of match) {
            if (!consumedKeys.has(m.key)) {
                merged.push({ ...m });
            }
        }

        return merged;
    }

    private _mergeParamRow(
        existing: NonNullable<ApiEndpoint['params']>[number],
        match: NonNullable<ApiEndpoint['params']>[number]
    ): NonNullable<ApiEndpoint['params']>[number] {
        const enumMerged = existing.enum && existing.enum.length ? existing.enum : match.enum;
        const description = existing.description?.trim() ? existing.description : match.description;

        return {
            ...match,
            ...existing,
            enum: enumMerged,
            description,
            dependencyGroup: existing.dependencyGroup ?? match.dependencyGroup,
            requiredWhen: existing.requiredWhen ?? match.requiredWhen,
            dateFormat: existing.dateFormat ?? match.dateFormat,
        };
    }

    private _mergeEndpoints(
        current: ApiEndpoint[],
        dynamicEndpoints: ApiEndpoint[]
    ): ApiEndpoint[] {
        const matchedDynamicIds = new Set<string>();

        const mergedCurrent = current.map((existing) => {
            const match = dynamicEndpoints.find((dynamic) =>
                this._isSameEndpoint(existing, dynamic)
            );
            if (!match) {
                return existing;
            }

            matchedDynamicIds.add(match.id);

            return {
                ...match,
                id: existing.id,
                label: existing.label || match.label,
                method: existing.method || match.method,
                url: existing.url || match.url,
                headers: existing.headers?.length ? existing.headers : match.headers,
                params: this._mergeEndpointParams(existing.params, match.params),
                body: existing.body ?? match.body,
                documentationUrl: existing.documentationUrl || match.documentationUrl,
                dependencies: match.dependencies?.length
                    ? match.dependencies
                    : existing.dependencies,
            };
        });

        const newEndpoints = dynamicEndpoints.filter(
            (endpoint) => !matchedDynamicIds.has(endpoint.id)
        );

        return [...mergedCurrent, ...newEndpoints];
    }

    private _isSameEndpoint(left: ApiEndpoint, right: ApiEndpoint): boolean {
        if (left.code && right.code && left.code === right.code) {
            return true;
        }

        return this._normalizeUrl(left.url) === this._normalizeUrl(right.url);
    }

    private _normalizeUrl(url: string): string {
        return url.replace(environment.apiUrl, '').replace(/^\/+/, '');
    }

    /** Flatten folders depth-first for “Move to” menus (label with indent). */
    flattenFoldersForMenu(): { id: string; label: string }[] {
        const folders = this.layoutFolders();
        const roots = folders
            .filter((f) => f.parentFolder == null || f.parentFolder === '')
            .sort(
                (a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0) || a.name.localeCompare(b.name)
            );

        const result: { id: string; label: string }[] = [];

        const walk = (list: PostmanFolderDto[], depth: number) => {
            for (const f of list) {
                const pad = depth > 0 ? `${'— '.repeat(depth)}` : '';
                result.push({ id: f._id, label: `${pad}${f.name}` });
                const kids = folders
                    .filter((x) => x.parentFolder === f._id)
                    .sort(
                        (a, b) =>
                            (a.sortOrder ?? 0) - (b.sortOrder ?? 0) || a.name.localeCompare(b.name)
                    );
                walk(kids, depth + 1);
            }
        };

        walk(roots, 0);
        return result;
    }

    createFolder(name: string, parentFolder?: string | null): Observable<unknown> {
        const body: Record<string, unknown> = { name: name.trim() };
        if (parentFolder) {
            body['parentFolder'] = parentFolder;
        }
        return this._httpClient.post(`${this._apiUrl()}/v2/postman/folders`, body, {
            headers: this._authHeaders(),
        });
    }

    updateFolder(
        folderId: string,
        patch: {
            name?: string;
            description?: string;
            sortOrder?: number;
            parentFolder?: string | null;
        }
    ): Observable<unknown> {
        return this._httpClient.put(`${this._apiUrl()}/v2/postman/folders/${folderId}`, patch, {
            headers: this._authHeaders(),
        });
    }

    deleteFolder(
        folderId: string,
        options?: { deleteEndpointLayouts?: boolean }
    ): Observable<unknown> {
        let params = new HttpParams();
        if (options?.deleteEndpointLayouts) {
            params = params.set('deleteEndpointLayouts', 'true');
        }
        return this._httpClient.delete(`${this._apiUrl()}/v2/postman/folders/${folderId}`, {
            headers: this._authHeaders(),
            params,
        });
    }

    /**
     * Creates or updates a PostmanEndpoint row to assign folder / metadata.
     */
    upsertEndpointLayout(
        endpoint: ApiEndpoint,
        patch: {
            folder?: string | null;
            displayName?: string;
            sortOrder?: number;
            isFavorite?: boolean;
        }
    ): Observable<unknown> {
        if (!endpoint.code) {
            return throwError(() => new Error('Endpoint has no app feature code'));
        }
        const headers = this._authHeaders();
        const base = `${this._apiUrl()}/v2/postman/endpoints`;

        if (endpoint.postmanEndpointId) {
            return this._httpClient.put(`${base}/${endpoint.postmanEndpointId}`, patch, {
                headers,
            });
        }

        return this._httpClient.post(
            base,
            {
                appFeatureCode: endpoint.code,
                folder: patch.folder ?? null,
                displayName: patch.displayName ?? endpoint.layoutDisplayName ?? '',
                sortOrder: patch.sortOrder ?? endpoint.layoutSortOrder ?? 0,
                isFavorite: patch.isFavorite ?? endpoint.isFavorite ?? false,
            },
            { headers }
        );
    }

    selectEndpoint(endpoint: ApiEndpoint) {
        const endpointCopy = JSON.parse(JSON.stringify(endpoint));

        if (endpointCopy.headers) {
            endpointCopy.headers.forEach((h: any) => {
                if (h.key === 'Authorization' && h.value.includes('<token>')) {
                    const token = localStorage.getItem('accessToken');
                    if (token) {
                        h.value = h.value.replace('<token>', token);
                    }
                }
            });
        }

        if (this._accountEnv.showSandboxStrip()) {
            applyPostmanSandboxParamDefaults(endpointCopy);
        }

        const withCost =
            this.paymentMethod() === 'credits'
                ? ensurePostmanIncludeCostParam(endpointCopy)
                : removePostmanIncludeCostParam(endpointCopy);

        this.selectedEndpoint.set(withCost);
        this.response.set(null);
        this.error.set(null);
        this.hydrateEndpointDetails(withCost).subscribe((hydrated) => {
            this.selectedEndpoint.update((current) => {
                if (!current || !this._isSameEndpoint(current, hydrated)) return current;
                return {
                    ...current,
                    ...hydrated,
                    headers: current.headers?.length ? current.headers : hydrated.headers,
                    params: this._mergeEndpointParams(current.params, hydrated.params),
                    body: current.body ?? hydrated.body,
                };
            });
            if (!hydrated.docs) return;
            this.endpoints.update((list) =>
                list.map((endpoint) =>
                    this._isSameEndpoint(endpoint, hydrated)
                        ? { ...endpoint, docs: hydrated.docs }
                        : endpoint
                )
            );
        });
    }

    sendRequest(endpoint: ApiEndpoint) {
        const postDraft =
            endpoint.method === 'GET' || endpoint.method === 'DELETE'
                ? undefined
                : JSON.stringify(
                      endpoint.body && typeof endpoint.body === 'object' ? endpoint.body : {},
                      null,
                      2
                  );
        if (getPostmanRequestValidationIssues(endpoint, postDraft).length > 0) {
            return;
        }

        const isX402 = this.paymentMethod() === 'x402';
        if (!isX402 && !this._sessionService.isTokenValid()) {
            this._sessionService.openAuthModal();
            return;
        }

        this.isLoading.set(true);
        this.response.set(null);
        this.error.set(null);

        const effectiveUrl = buildPostmanEffectiveUrl(endpoint);
        const pathParamKeys = getPostmanPathParamKeysForEndpoint(endpoint);

        let url = effectiveUrl;
        const options: any = {
            headers: {},
            params: {},
        };

        if (isX402) {
            url = `${environment.smartAgentUrl}/api/proxy`;

            const paymentTxHeader = endpoint.headers?.find((h) => h.key === 'x-payment-tx');
            const walletAddressHeader = endpoint.headers?.find((h) => h.key === 'x-wallet-address');

            options.headers['x-payment-tx'] = paymentTxHeader?.value || '';
            options.headers['x-wallet-address'] = walletAddressHeader?.value || '';
            options.headers['x-target-url'] = effectiveUrl;
            options.headers['Content-Type'] = 'application/json';
        } else {
            if (endpoint.headers) {
                endpoint.headers.forEach((h) => {
                    let value = h.value;
                    if (value && value.includes('<token>')) {
                        const token = localStorage.getItem('accessToken') || '';
                        value = value.replace('<token>', token);
                    }
                    options.headers[h.key] = value;
                });
            }
        }

        if (endpoint.params) {
            endpoint.params.forEach((p) => {
                if (!p.value) {
                    return;
                }
                if (pathParamKeys?.includes(p.key)) {
                    return;
                }
                // The includeCost row is handled separately by resolvePostmanIncludeCostForSend.
                // A blank key is an unfinished row. A key the user typed, including force, is sent.
                if (!p.key || p.key === POSTMAN_INCLUDE_COST_KEY) {
                    return;
                }
                options.params[p.key] =
                    p.key === 'sexo' ? normalizePostmanSexoValue(p.value) : p.value;
            });
        }

        let body = null;
        if (endpoint.method !== 'GET' && endpoint.method !== 'DELETE') {
            body = endpoint.body && typeof endpoint.body === 'object' ? { ...endpoint.body } : {};
            if (body && typeof body.sexo === 'string') {
                body.sexo = normalizePostmanSexoValue(body.sexo);
            }
        }

        if (!isX402) {
            const costSend = resolvePostmanIncludeCostForSend(endpoint, endpoint.method);
            if (costSend.query) {
                options.params.includeCost = costSend.query;
            }
            if (costSend.body && body !== null) {
                body = { ...body, includeCost: true };
            }
        }

        const startTime = Date.now();
        const req$ = this._httpClient.request(endpoint.method, url, {
            ...options,
            body: body,
            observe: 'response',
        });

        req$.pipe(
            tap((res) => {
                const anyRes = res as any;
                const proof = anyRes.headers ? anyRes.headers.get('x-validation-proof') : null;

                if (anyRes.body && typeof anyRes.body === 'object') {
                    anyRes.body._proof = proof || anyRes.body._proof;
                }

                this.isLoading.set(false);
                this.response.set(res);
                this.responseTime.set(Date.now() - startTime);

                this._refreshCredits(anyRes?.status);
            }),
            catchError((err) => {
                this.isLoading.set(false);
                if (!isX402 && err?.status === 401) {
                    this._sessionService.openAuthModal();
                    return of(null);
                }
                this.error.set(err);
                this._refreshCredits(err?.status);
                return of(null);
            }),
            finalize(() => {
                this._refreshWalletForX402();
            })
        ).subscribe();
    }

    /**
     * Refreshes session credits after a Postman call in `credits` mode whenever the
     * backend produced a real HTTP response (any status > 0, including 4xx like 404 and
     * 5xx). Network errors (status === 0) are skipped because no credit was consumed.
     */
    private _refreshCredits(status: number | undefined): void {
        if (this.paymentMethod() !== 'credits') return;
        if (!status || status <= 0) return;
        if (!this._sessionService.isTokenValid()) return;

        this._authService.refreshSession().subscribe({
            error: () => {
                /* swallow: keep current cached user if refresh fails */
            },
        });
    }

    /**
     * Refreshes wallet balances after every Postman call in `x402` mode (success, error,
     * or 402 retry) so AVAX/VKA in the header stay aligned with the on-chain state.
     */
    private _refreshWalletForX402(): void {
        if (this.paymentMethod() !== 'x402') return;

        void this._agentWalletService.refreshBalance();
    }
}
